class Stories{static instances=[];static observer=null;constructor(container){this.container=container;this.elements=Array.from(container.querySelectorAll(".dan-stories__story"));this.controls=container.querySelector(".dan-stories__controls");this.thumbContainer=this.controls.querySelector(".dan-stories__controls-thumb");this.duration=parseFloat(container.getAttribute("data-duration"))*1000;this.ease=container.getAttribute("data-ease")||"none";this.timeout=null;this.pausedTimeout=null;this.index=0;this.slide=this.elements[this.index];this.paused=!1;this.thumbItems=null;this.thumb=null;this.activeVideo=null;this.onPointerDown=()=>this.pause();this.onPointerUp=()=>this.continue();this.onTouchEnd=()=>this.continue();this.elements.forEach((el)=>el.setAttribute("inert",""));this.init()}
init(){this.createThumbs();this.addControls();this.show(this.index)}
getSlideVideo(slide){if(!slide||typeof slide.querySelector!=="function"){return null}
return slide.querySelector("video")}
safePlay(video){if(!video||typeof video.play!=="function"){return}
const playPromise=video.play();if(playPromise&&typeof playPromise.catch==="function"){playPromise.catch((error)=>{if(!error||error.name!=="AbortError"){console.warn("Dancepad Stories video playback issue:",error)}})}}
createThumbs(){this.thumbContainer.innerHTML="";this.elements.forEach(()=>{const span=document.createElement("span");const thumb=document.createElement("span");thumb.classList.add("thumb-item");span.appendChild(thumb);this.thumbContainer.appendChild(span)});this.thumbItems=Array.from(this.thumbContainer.querySelectorAll(".thumb-item"))}
addControls(){const btnPrev=document.createElement("button");const btnNext=document.createElement("button");btnPrev.setAttribute("aria-label","Previous");btnNext.setAttribute("aria-label","Next");btnPrev.addEventListener("keydown",(e)=>{if(e.key==="Enter")this.prev();});btnNext.addEventListener("keydown",(e)=>{if(e.key==="Enter")this.next();});btnPrev.addEventListener("pointerup",()=>this.prev());btnNext.addEventListener("pointerup",()=>this.next());this.controls.appendChild(btnPrev);this.controls.appendChild(btnNext);this.controls.addEventListener("pointerdown",this.onPointerDown);document.addEventListener("pointerup",this.onPointerUp);document.addEventListener("touchend",this.onTouchEnd)}
hide(el){const video=this.getSlideVideo(el);el.classList.remove("active");if(video){video.pause();video.muted=!0;video.currentTime=0}}
show(index){this.index=index;this.slide=this.elements[this.index];if(this.thumbItems){this.thumb=this.thumbItems[this.index];this.thumbItems.forEach((t)=>t.classList.remove("active"));this.thumb.classList.add("active")}
this.elements.forEach((el)=>this.hide(el));this.slide.classList.add("active");this.activeVideo=this.getSlideVideo(this.slide);if(this.thumb){const duration=this.activeVideo&&isFinite(this.activeVideo.duration)&&this.activeVideo.duration>0?this.activeVideo.duration:this.duration/1000;if(!this.thumb.timeline){this.thumb.timeline=gsap.timeline({paused:!0});this.thumb.timeline.fromTo(this.thumb,{x:"-100%"},{x:"0%",duration:duration,ease:this.ease})}else{this.thumb.timeline.duration(duration)}
this.thumb.timeline.restart()}
if(this.activeVideo){this.activeVideo.controls=!1;this.activeVideo.currentTime=0;this.safePlay(this.activeVideo);const videoDurationMs=isFinite(this.activeVideo.duration)&&this.activeVideo.duration>0?this.activeVideo.duration*1000:this.duration;this.auto(videoDurationMs)}else{this.auto(this.duration)}}
auto(ms){if(this.timeout)this.timeout.clear();this.timeout=new StoriesTimeout(()=>this.next(),ms)}
next(){if(!this.paused){const nextIndex=this.index+1<this.elements.length?this.index+1:0;this.show(nextIndex)}}
prev(){if(!this.paused){const prevIndex=this.index-1>=0?this.index-1:this.elements.length-1;this.show(prevIndex)}}
pause(){this.pausedTimeout=new StoriesTimeout(()=>{this.paused=!0;this.timeout?.pause();this.thumb?.classList.add("paused");if(this.thumb?.timeline)this.thumb.timeline.pause();if(this.activeVideo)this.activeVideo.pause();},300)}
continue(){this.pausedTimeout?.clear();if(this.paused){this.paused=!1;this.timeout?.continue();this.thumb?.classList.remove("paused");if(this.thumb?.timeline)this.thumb.timeline.play();if(this.activeVideo)this.safePlay(this.activeVideo);}}
destroy(){this.timeout?.clear();this.pausedTimeout?.clear();this.controls?.removeEventListener("pointerdown",this.onPointerDown);document.removeEventListener("pointerup",this.onPointerUp);document.removeEventListener("touchend",this.onTouchEnd);this.thumbItems?.forEach((thumb)=>{if(thumb.timeline){thumb.timeline.kill();thumb.removeAttribute("style")}})}
static destroyAllInstances(){Stories.instances.forEach((instance)=>instance.destroy());Stories.instances=[]}
static initMutationObserver(){if(Stories.observer){Stories.observer.disconnect()}
Stories.observer=new MutationObserver((mutations)=>{let shouldReinitialize=!1;mutations.forEach((mutation)=>{if(mutation.type==="childList"){mutation.addedNodes.forEach((node)=>{if(node.nodeType===Node.ELEMENT_NODE){if(node.classList&&node.classList.contains("dan-stories__story")){shouldReinitialize=!0}else if(node.querySelector&&node.querySelector(".dan-stories__story")){shouldReinitialize=!0}}});mutation.removedNodes.forEach((node)=>{if(node.nodeType===Node.ELEMENT_NODE){if(node.classList&&node.classList.contains("dan-stories__story")){shouldReinitialize=!0}else if(node.querySelector&&node.querySelector(".dan-stories__story")){shouldReinitialize=!0}}})}});if(shouldReinitialize){setTimeout(()=>{dancepad_stories()},100)}});document.querySelectorAll(".dan-stories").forEach((container)=>{const elementsContainer=container.querySelector(".dan-stories__container");if(elementsContainer){Stories.observer.observe(elementsContainer,{childList:!0,subtree:!0})}})}}
class StoriesTimeout{constructor(handler,duration){this.handler=handler;this.timeLeft=duration;this.id=setTimeout(handler,duration);this.start=Date.now()}
clear(){clearTimeout(this.id)}
pause(){const elapsed=Date.now()-this.start;this.timeLeft-=elapsed;this.clear()}
continue(){this.clear();this.id=setTimeout(this.handler,this.timeLeft);this.start=Date.now()}}
function dancepad_stories(){Stories.destroyAllInstances();const isBreakdance=window.location.href.includes("breakdance");document.querySelectorAll(".dan-stories").forEach((container)=>{container.removeAttribute("data-flickering");if(isBreakdance&&container.getAttribute("data-disable-builder")?.includes("1")){return}
const elements=container.querySelector(".dan-stories__container");const controls=container.querySelector(".dan-stories__controls");if(!elements||!controls){return}
const stories=elements.querySelectorAll(".dan-stories__story");if(stories.length){const instance=new Stories(container);Stories.instances.push(instance)}});Stories.initMutationObserver()}